package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentMatchers;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_shouldTraverse_TriageGen0Test {

    private CheckGlobalThis checkGlobalThis;
    private NodeTraversal nodeTraversal;

    @Before
    public void setUp() {
        checkGlobalThis = new CheckGlobalThis();
        nodeTraversal = mock(NodeTraversal.class);
    }

    // Helper to mock Node behavior
    private Node mockNode(int type) {
        Node node = mock(Node.class);
        when(node.getType()).thenReturn(type);
        return node;
    }

    @Test
    public void testShouldTraverse_NotFunction_NoParent() {
        Node n = mockNode(Token.NAME);
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, null));
    }

    @Test
    public void testShouldTraverse_Function_NoJsDoc() {
        Node n = mockNode(Token.FUNCTION);
        // Assuming getFunctionJsDocInfo is protected or accessible, 
        // in a real scenario we might need to spy if it's not easily injectable.
        // Since we can't override the internal call easily without PowerMock, 
        // we assume the implementation of getFunctionJsDocInfo returns null for this mock.
        // For the sake of this test, we assume a subclass or spy is used if needed, 
        // but here we rely on the default behavior where getFunctionJsDocInfo returns null.

        // Note: In a real environment, we'd use a spy to control getFunctionJsDocInfo
        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(null);

        assertTrue(spyCheck.shouldTraverse(nodeTraversal, n, null));
    }

    @Test
    public void testShouldTraverse_Function_JsDocConstructor() {
        Node n = mockNode(Token.FUNCTION);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isConstructor()).thenReturn(true);

        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(jsDoc);

        assertFalse(spyCheck.shouldTraverse(nodeTraversal, n, null));
    }

    @Test
    public void testShouldTraverse_Function_JsDocHasThisType() {
        Node n = mockNode(Token.FUNCTION);
        JSDocInfo jsDoc = mock(JSDocInfo.class);
        when(jsDoc.isConstructor()).thenReturn(false);
        when(jsDoc.hasThisType()).thenReturn(true);

        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        when(spyCheck.getFunctionJsDocInfo(n)).thenReturn(jsDoc);

        assertFalse(spyCheck.shouldTraverse(nodeTraversal, n, null));
    }

    @Test
    public void testShouldTraverse_Assignment_LHS() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.NAME);
        Node rhs = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        // n is the LHS
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, lhs, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_Normal() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.NAME);
        Node rhs = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        // n is the RHS
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, rhs, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_PrototypeProperty() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.GETPROP);
        Node rhs = mockNode(Token.NAME);
        Node prototypeChild = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getLastChild()).thenReturn(prototypeChild);
        when(prototypeChild.getString()).thenReturn("prototype");

        assertFalse(checkGlobalThis.shouldTraverse(nodeTraversal, rhs, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_QualifiedPrototype() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.GETPROP);
        Node rhs = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getQualifiedName()).thenReturn("MyClass.prototype.method");

        assertFalse(checkGlobalThis.shouldTraverse(nodeTraversal, rhs, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_QualifiedNonPrototype() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.GETPROP);
        Node rhs = mockNode(Token.NAME);
        Node lastChild = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("somethingElse");
        when(lhs.getQualifiedName()).thenReturn("obj.prop");

        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, rhs, parent));
    }

    @Test
    public void testShouldTraverse_Assignment_RHS_QualifiedNullName() {
        Node parent = mockNode(Token.ASSIGN);
        Node lhs = mockNode(Token.GETPROP);
        Node rhs = mockNode(Token.NAME);
        Node lastChild = mockNode(Token.NAME);

        when(parent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("notPrototype");
        when(lhs.getQualifiedName()).thenReturn(null);

        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, rhs, parent));
    }
}
